import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"Ports (PX4)","description":"","frontmatter":{},"headers":[],"relativePath":"en/qgc-user-guide/setup_view/px4/ports.md","filePath":"en/qgc-user-guide/setup_view/px4/ports.md"}`),a={name:`en/qgc-user-guide/setup_view/px4/ports.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="ports-px4" tabindex="-1">Ports (PX4) <a class="header-anchor" href="#ports-px4" aria-label="Permalink to “Ports (PX4)”">​</a></h1><p>The Ports page assigns functions such as MAVLink telemetry, GPS and RC input to the vehicle&#39;s serial ports, and to Ethernet on boards that have it.</p><p>PX4 stores this per function: each function has a parameter (for example <code>MAV_0_CONFIG</code> or <code>GPS_1_CONFIG</code>) that selects the port it runs on. This page shows the same settings with one row per port. It is only shown for PX4 builds that have serial port functions, so it does not appear for SITL.</p><h2 id="port-rows" tabindex="-1">Port Rows <a class="header-anchor" href="#port-rows" aria-label="Permalink to “Port Rows”">​</a></h2><p>Each row shows:</p><ul><li><strong>Port</strong> — the port name used by the flight controller, such as <em>TELEM 1</em> or <em>GPS 1</em>. Below the name are the parameters that put a function on the port, for example <code>GPS_1_CONFIG = 201</code>. The dot next to the name is green when a function is on the port, and orange when the port needs a reboot or has a conflict.</li><li><strong>Function</strong> — what runs on the port. The functions normally used on that kind of port are listed first. Any function can run on any serial port, so the list also includes the others.</li><li><strong>Baud</strong> — the port&#39;s baud rate (<code>SER_&lt;port&gt;_BAUD</code>). Ethernet has no baud rate.</li><li><strong>Options</strong> — extra settings for the selected function: mode, rate, forwarding and flow control for MAVLink, and protocol for GPS.</li></ul><p>Selecting a function for a serial port removes any other function from that port. Several functions can use Ethernet at the same time, so the Ethernet row shows a checkbox for each one instead.</p><p>The page opens on <strong>In Use</strong> when any port has a function, showing only the ports that have a function or a change waiting for a reboot. Select <strong>All Ports</strong> to show every port.</p><p><em>Loading...</em> is shown while QGroundControl reads a setting that the vehicle did not send in its parameter list. PX4 only sends a port&#39;s baud rate and options once a function is using them.</p><p>If more than one function is assigned to the same serial port, the row shows a warning: only one of them will start.</p><p>PX4 always starts the RC Input Driver. Setting it to <em>Disabled</em> does not stop it: it then uses the board&#39;s default RC port. So the RC Input Driver stays on the <em>Radio Controller</em> port until it is assigned to another port: that port has no <em>None</em> choice meanwhile, and another function assigned there is shown as a conflict.</p><h2 id="applying-changes" tabindex="-1">Applying Changes <a class="header-anchor" href="#applying-changes" aria-label="Permalink to “Applying Changes”">​</a></h2><p>Changes are written to the vehicle immediately, but all of these settings only take effect after the vehicle reboots. Changed rows are marked <em>Reboot required</em>, and a banner at the top of the page offers:</p><ul><li><strong>Reboot Vehicle</strong> — reboot to apply the changes (not available while armed).</li><li><strong>Revert Changes</strong> — write back the values the settings had when the page was opened.</li></ul><p>Both buttons are disabled until the vehicle has acknowledged every change, so a slow link can&#39;t apply only part of one.</p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};